+
+    /*
+     * Detect unusual TCP control-flag combinations.  These segments are
+     * syntactically well-formed; it is the simultaneous combination of the
+     * control flags that is rarely (if ever) produced by normal TCP traffic
+     * and that is commonly associated with port scanning and OS
+     * fingerprinting (Nmap FIN/NULL/XMAS).  Reported as PI_PROTOCOL (not
+     * PI_MALFORMED) because dissection continues normally, and not as part
+     * of tcp.analysis.flags because these do not depend on conversation
+     * sequence-number state.  Anchored on the parent flags item so the
+     * warning reads as applying to the whole flags field.
+     *
+     * XMAS: FIN+PSH+URG.  No legitimate application is expected to generate
+     * this triad; it is the Nmap -sX fingerprint.  The check is on the
+     * presence of all three bits, so any additional flags (e.g.
+     * FIN+PSH+URG+ACK) are also flagged: the triad is the anomalous marker
+     * regardless of the other flag bits.
+     */
+    if ((tcph->th_flags & (TH_FIN|TH_PUSH|TH_URG)) == (TH_FIN|TH_PUSH|TH_URG)) {
+        expert_add_info(pinfo, flags_item, &ei_tcp_flags_xmas);
+    }
+
+    /*
+     * NULL: no control flags set.  RFC 9293 requires the ACK bit in every
+     * segment after the initial SYN and defines no state transition for a
+     * flagless segment, which is the basis for its association with NULL
+     * scanning.  The mask covers all control bits including the AccECN AE
+     * bit (RFC 9293), so a segment with AE set is not treated as NULL; the
+     * reserved bits are excluded and are instead reported via
+     * hf_tcp_flags_res.
+     */
+    if ((tcph->th_flags &
+        (TH_FIN|TH_SYN|TH_RST|TH_PUSH|TH_ACK|TH_URG|TH_ECE|TH_CWR|TH_AE)) == 0) {
+        expert_add_info(pinfo, flags_item, &ei_tcp_flags_null);
+    }
+
+    /* SYN+FIN: the pair is contradictory (connection establishment vs.
+     * teardown) and is a recognized probing/fingerprinting pattern.
+     * Any additional flags (e.g. SYN+FIN+ACK) are intentionally included
+     * since the SYN+FIN pair is the anomalous marker.
+     */
+    if ((tcph->th_flags & (TH_SYN|TH_FIN)) == (TH_SYN|TH_FIN)) {
+        expert_add_info(pinfo, flags_item, &ei_tcp_flags_syn_fin);
+    }
+
     if(tcp_analyze_seq
             && (tcph->th_flags & (TH_SYN|TH_ACK)) == TH_ACK
             && !nstime_is_zero(&tcpd->ts_mru_syn)
